import java.sql.*;import java.nio.file.*;import java.util.*;import java.security.*;
public class SafeProbe {
 static Map<String,String> snapshot(Connection c)throws Exception{Map<String,String> out=new TreeMap<>();try(var r=c.getMetaData().getTables(null,null,"%",new String[]{"BASE TABLE","TABLE"})){while(r.next()){String t=r.getString("TABLE_NAME");if(!t.toLowerCase().startsWith("mate_semantic_"))continue;List<String> rows=new ArrayList<>();try(var s=c.createStatement();var q=s.executeQuery("SELECT * FROM "+t)){while(q.next()){StringBuilder b=new StringBuilder();for(int i=1;i<=q.getMetaData().getColumnCount();i++){String v=q.getString(i);b.append(v==null?"NULL":v.length()+":"+v).append("|");}rows.add(b.toString());}}Collections.sort(rows);var d=MessageDigest.getInstance("SHA-256");for(String row:rows)d.update(row.getBytes(java.nio.charset.StandardCharsets.UTF_8));out.put(t,rows.size()+":"+HexFormat.of().formatHex(d.digest()));}}return out;}
 public static void main(String[] args)throws Exception{Path dir=Path.of(args[0]).toRealPath();if(!dir.toString().contains("/runtime/isolated-"))throw new IllegalArgumentException("isolated path required");String url="jdbc:h2:file:"+dir+"/copy;MODE=MySQL;DATABASE_TO_LOWER=TRUE;CASE_INSENSITIVE_IDENTIFIERS=TRUE;IFEXISTS=TRUE";Map<String,String> before;try(var c=DriverManager.getConnection(url,"sa","")){before=snapshot(c);try(var s=c.createStatement()){s.execute("SCRIPT TO '"+dir+"/restore.sql'");}}
 try(var c=DriverManager.getConnection("jdbc:h2:file:"+dir+"/restored;MODE=MySQL;DATABASE_TO_LOWER=TRUE;CASE_INSENSITIVE_IDENTIFIERS=TRUE","sa","")){try(var s=c.createStatement()){s.execute("RUNSCRIPT FROM '"+dir+"/restore.sql'");}var after=snapshot(c);if(!before.equals(after))throw new AssertionError("restore digest mismatch");System.out.println("PASS backup copy open + SQL restore; semantic table count="+before.size());before.forEach((k,v)->System.out.println(k+"="+v));}}
}